import type { Locale } from "@/lib/i18n";
import type { GeoPageContent } from "@/lib/geoPageContent";
import pediatricEnvironmentHero from "@/img/generated/pediatric-environment-hero.webp";
import cancerTreatment from "@/img/cancertreatmentstockphoto2.jpg";
import hockeyArena from "@/img/hockey arena stock photo.jpg";
import hockeyHero from "@/img/hockey-hero-rising-stockcake.jpg";

const hockeyEnvironmentSections = {
  en: [
    ["Artistically Competitive", "Ice hockey is very similar to the fight against life-threatening illness, such as pediatric cancer or heart disease, because it requires artistry in designing early detection methods and innovative treatment plans, while simultaneously requiring patients to fight for their lives every day emotionally, mentally, and physically. No two journeys look the same, especially when it comes to cancer. Sometimes, patients will look like artistic skaters handling the journey with grace and agility, while others will look like determined competitors showing up every day to fight for themselves, their loved ones, and their fellow patients in their journey to survive."],
    ["Graceful Speed", "In ice hockey, when a player is aware of his surroundings, movement up and down the ice can be generated with graceful speed. Likewise, awareness of signs and symptoms of life-threatening illness, such as pediatric cancer or heart disease, is essential in assessing and addressing these conditions with graceful speed."],
    ["Agile Mobility", "Ice hockey players are some of the most agile athletes on the face of the planet, both mentally and physically, because in order to play the sport, they have to learn an entirely different mode of transportation, then learn the sport strategy in addition to that. The players who master this skill can utilize that agile mobility to fake out defenders, score incredibly beautiful goals, and execute precision passes to assist other teammates in scoring goals. Patients battling life-threatening illness, such as pediatric cancer or heart disease, often are forced to learn new modes of transportation to navigate through life, at least temporarily. With the right equipment and environment, patients can be encouraged to harness that new mode of transportation to pull off dazzling moves on their journey, allowing them to score incredible goals of survival and assist their fellow patients with precision inspiration every step of the way."],
    ["Balancing Act", "An essential part of ice hockey is balancing on a 3 to 4 millimeter piece of steel to glide around the ice surface. Patients battling life-threatening illness, such as pediatric cancer or heart disease, have to exercise the same balance when their world is completely altered by such a diagnosis. Patients are asked to balance treatment plans with school, work, rest, and everyday life. The right supportive, morale boosting environment can make this learning process feel less daunting, and empower patients to be successful on their journey."],
    ["Stopping power", "When ice hockey players stay alert, they possess the incredible ability to stop and turn away from obstacles that are in their path, even when they are skating at full speed. Similarly, early detection of life-threatening illness, such as pediatric cancer or heart disease, can provide patients with incredible stopping power, allowing them the opportunity to avoid debilitating obstacles in their way. Therefore, a kid friendly, ice hockey themed research environment must make education about early detection methods a priority without sacrificing the importance of researching more effective treatment plans for after the illness is properly identified."],
    ["Gritty Determination", "Not all hockey players are nimble skaters or flashy goal scorers, some are highly valued for their willingness to battle for possession of the puck in difficult areas along the walls of the rink with grit and determination, even if that means simultaneously having to fend off three or four different opponents who are also trying to possess the puck. Not all patients get the luxury of battling a life-threatening illness that was diagnosed through early detection, in which case the journey is never pretty or flashy, and even if the illness was detected early, there’s never a guarantee that a relapse will be detected early. It will require patients to battle every day for survival, sometimes in the hard areas with multiple obstacles trying to stop them. Our vision for a kid friendly, ice hockey themed research facility is important to boost morale for these brave individuals, and make sure that their every day battles do not go unnoticed or unappreciated. Note: Even in a supportive, morale boosting environment such as this, patients are allowed to feel tired, worried, or frustrated, but are always encouraged to persevere with grit and determination."],
    ["Warrior Mentality", "They call it the Identity Line, a group of players who show up every day like faithful warriors to compete for loose pucks, take a hit to make a play, and be the unsung heroes that anchor a championship hockey team. Some patients will look more like this kind of player, rather than a goal scorer or an assist machine, and every day, a hockey themed environment will allow the message “We see you, We appreciate you” to be heard loud and clear to all those patients who fight every day whether they make the highlight reel or not."],
    ["Resilient Competition", "In North American professional ice hockey, it takes winning 16 out of a potential 28 games to win the championship. Not all players will succeed, but every player that earns the opportunity to compete in that tournament battles to the end with incredible resiliency, in spite of great pain and hardship along the way. While patients do not ask to participate in a battle against life-threatening illness, such as pediatric cancer or heart disease, they should always be encouraged to fight to the end with incredible resiliency in spite of great and painful difficulty, no matter the outcome. Note: One of the great traditions at the end of every stage of the tournament is the handshake line where everyone has a chance to celebrate the effort it took to get to that point, so whether they succeed in hoisting the trophy or not, patients should always be commemorated and validated for resiliently competing to the end."],
    ["Friendly Neighborhood Mascots", "In sports, a welcoming and endearing mascot can make the game experience memorable and lead to a lot of positive memories for fans and players alike. The same is true in ice hockey, and in our kid-friendly research environment, these mascots would play a key role in boosting the morale of patients and staff."],
    ["Laughter", "Nothing quite compares to the zany antics of a favorite hockey mascot to make fans and players laugh with joy. The fight against life-threatening illness, such as pediatric cancer or heart disease, is filled with many negative emotions, but positive laughter can fill a treatment area with joy, and offer a welcome break from clinical routines."],
    ["Enthusiasm", "Depression is all too familiar for patients fighting life-threatening illness, such as pediatric cancer or heart disease, however, a well-timed visit by a favorite, enthusiastic hockey mascot can brighten even the darkest of days with fun-filled memories."],
    ["Teamwork", "A favorite hockey mascot embodies team spirit. Whether that’s dancing to energize the crowd, shooting T-Shirts out of a cannon, or driving the visiting team crazy, the mascot is focused on supporting the home team, no matter what. It is this team spirit energy that can make a kid-friendly hockey themed research environment so supportive for the patients that enter, whether the mascot is a big teddy bear handing out free hugs or a favorite staff member that makes a patient smile whenever they walk into the room."],
    ["Impressive Arenas", "True, ice hockey can be played on frozen backyard ponds or in community skating rinks, but nothing quite compares to the experience of visiting the splendorous venue of a professional team, regardless of the outcome of the game. While a clinical research environment is not one that people typically want to visit, when they do, it should inspire respect and boost morale regardless of the outcome, just like a well designed professional ice hockey venue."],
    ["Vocalized Support", "The best arenas have the best staff who care for your every need with a smile on their face. Caring for patients with life-threatening illness, such as pediatric cancer or heart disease, can be filled with both joy and grief, sometimes on the same day or in the same hour, so an innovative environment focused on boosting morale for patients can also make the workplace more fun for staff members, thus increasing the quality of care received by all around them. Don’t forget, staff members are patients too."],
    ["Home Ice Advantage", "For some patients, their journey means spending long periods of time away from the comforts of home. The kid-friendly, ice hockey themed research environment would include on-site housing that would be available to accommodate qualifying patients and staff to help boost morale by providing a “home ice advantage” while they fight life-threatening illness such as pediatric cancer or heart disease."],
    ["Practice Makes a Difference", "The most important part of the hockey game is what happens before the referee drops the puck…it’s the skills practiced during warm-ups and behind the scenes that make all the difference. Not all patients battling life-threatening illness are considered research cases, but every case can provide valuable research insight. Remember, a life-threatening illness is never a “typical case” for patients, and every lesson learned can save a person’s life."],
    ["Did Someone Say Food?", "One of the most memorable things about impressive sports venues is the wide variety of foods that are available, especially venues that like to highlight regional cuisine such as bbq and poutine. While hospitals are typically not known for their cuisine, our kid-friendly, ice hockey themed research environment would prioritize having delicious food available to patients and staff, without sacrificing nutrition or neglecting care plans. Note: According to Here To Serve, Inc. in Los Angeles, CA, 60% of the battle against cancer happens at home, so it is important to do our part to make sure that patients not only receive nutritious meals in a clinical facility, but also when they get home after many long hours of treatment."],
    ["Equipment Matters", "The sport of ice hockey cannot be played without specialized equipment. The same can be said for patients battling life-threatening illness such as pediatric cancer or heart disease."],
    ["Rubber Pucks and Hockey Sticks", "The fundamental principle of ice hockey is to navigate a 3 inch rubber puck across a 200 foot, obstacle filled ice surface with a stick, so strong puck movement is critical to success. For every patient diagnosed with a life-threatening illness such as pediatric cancer or heart disease, a survival percentage is stated. The patient has to then take that percentage and navigate across an environment filled with obstacles in an attempt to either beat or increase the percentage, depending on the perspective. Like the hockey stick, a patient’s physical, emotional, and mental health is all they have to move the puck down the ice, so it is important that we give them every chance to succeed in skating all the way to the goal. A kid-friendly, ice hockey themed research environment can provide clinical care to safeguard physical health and boost morale to safeguard both emotional and mental health."],
    ["Clean Ice (Zamboni machines)", "In between ice hockey periods, one of the most important pieces of equipment utilized is the Zamboni machine. It cleans the ice surface to make sure game play can be at the highest quality at the start of every 20 minute period. Likewise, in a kid-friendly research environment, disciplined environmental care is essential to make sure that patients can receive treatment at the highest quality possible."],
  ],
  "fr-CA": [
    ["Artistique et compétitif", "Le hockey sur glace ressemble beaucoup au combat contre une maladie potentiellement mortelle, comme le cancer pédiatrique ou une maladie cardiaque, puisqu’il faut faire preuve de créativité pour concevoir des méthodes de dépistage précoce et des plans de traitement novateurs, tandis que les patients doivent simultanément lutter chaque jour pour leur vie sur les plans émotionnel, mental et physique. Aucun parcours ne se ressemble, particulièrement lorsqu’il s’agit du cancer. Certains patients ressemblent parfois à des patineurs artistiques qui traversent cette épreuve avec grâce et agilité, tandis que d’autres ressemblent à des compétiteurs déterminés qui se présentent chaque jour pour lutter pour eux-mêmes, leurs proches et les autres patients dans leur parcours vers la survie."],
    ["Vitesse gracieuse", "Au hockey sur glace, un joueur conscient de ce qui l’entoure peut se déplacer sur la patinoire avec une vitesse gracieuse. De la même façon, connaître les signes et les symptômes d’une maladie potentiellement mortelle, comme le cancer pédiatrique ou une maladie cardiaque, est essentiel pour évaluer et traiter rapidement ces affections."],
    ["Mobilité agile", "Les joueurs de hockey sur glace comptent parmi les athlètes les plus agiles qui soient, tant mentalement que physiquement, car ils doivent apprendre un tout nouveau mode de déplacement avant même d’assimiler la stratégie du sport. Ceux qui maîtrisent cette habileté peuvent utiliser leur mobilité agile pour déjouer les défenseurs, marquer des buts d’une grande beauté et effectuer des passes précises qui aident leurs coéquipiers à marquer. Les patients qui luttent contre une maladie potentiellement mortelle, comme le cancer pédiatrique ou une maladie cardiaque, doivent souvent apprendre, au moins temporairement, de nouvelles façons de se déplacer dans la vie. Avec le bon équipement et le bon environnement, ils peuvent être encouragés à maîtriser ce nouveau mode de déplacement pour accomplir des manœuvres éblouissantes au fil de leur parcours, marquer des buts remarquables vers la survie et inspirer avec précision les autres patients à chaque étape."],
    ["Question d’équilibre", "Une composante essentielle du hockey sur glace consiste à garder l’équilibre sur une lame d’acier de trois à quatre millimètres pour glisser sur la patinoire. Les patients qui luttent contre une maladie potentiellement mortelle, comme le cancer pédiatrique ou une maladie cardiaque, doivent trouver ce même équilibre lorsque leur monde est complètement bouleversé par un tel diagnostic. Ils doivent concilier les plans de traitement, l’école, le travail, le repos et la vie quotidienne. Un environnement adéquat, encourageant et axé sur le moral peut rendre cet apprentissage moins intimidant et donner aux patients les moyens de progresser dans leur parcours."],
    ["Pouvoir d’arrêt", "Lorsqu’ils demeurent vigilants, les joueurs de hockey sur glace possèdent l’incroyable capacité de s’arrêter et de contourner les obstacles qui se dressent devant eux, même lorsqu’ils patinent à pleine vitesse. De la même façon, le dépistage précoce d’une maladie potentiellement mortelle, comme le cancer pédiatrique ou une maladie cardiaque, peut donner aux patients un remarquable pouvoir d’arrêt et leur permettre d’éviter des obstacles invalidants. Un milieu de recherche adapté aux enfants et inspiré du hockey sur glace doit donc accorder la priorité à l’éducation sur les méthodes de dépistage précoce, sans négliger l’importance de rechercher des traitements plus efficaces une fois la maladie correctement identifiée."],
    ["Détermination tenace", "Les joueurs de hockey ne sont pas tous des patineurs agiles ou des marqueurs spectaculaires. Certains sont grandement appréciés pour leur volonté de se battre avec ténacité et détermination pour prendre possession de la rondelle dans les zones difficiles le long de la bande, même lorsqu’ils doivent affronter simultanément trois ou quatre adversaires qui la convoitent aussi. Les patients n’ont pas tous la chance de lutter contre une maladie potentiellement mortelle détectée précocement; leur parcours n’est alors jamais élégant ni spectaculaire. Même lorsque la maladie a été détectée tôt, rien ne garantit qu’une rechute le sera également. Les patients doivent lutter chaque jour pour survivre, parfois dans les zones difficiles, alors que de nombreux obstacles tentent de les arrêter. Notre vision d’un milieu de recherche adapté aux enfants et inspiré du hockey sur glace vise à soutenir le moral de ces personnes courageuses et à faire en sorte que leurs combats quotidiens ne passent ni inaperçus ni inestimés. Remarque : même dans un environnement encourageant et axé sur le moral comme celui-ci, les patients ont le droit de se sentir fatigués, inquiets ou frustrés, tout en étant encouragés à persévérer avec ténacité et détermination."],
    ["Mentalité de guerrier", "On l’appelle le trio identitaire : un groupe de joueurs qui se présentent chaque jour comme de fidèles guerriers pour disputer les rondelles libres, encaisser une mise en échec afin de réussir un jeu et devenir les héros méconnus qui ancrent une équipe championne. Certains patients ressembleront davantage à ce type de joueur qu’à un marqueur ou à une machine à passes. Chaque jour, un environnement inspiré du hockey transmettra haut et fort le message « Nous vous voyons, nous vous apprécions » à tous les patients qui luttent quotidiennement, qu’ils apparaissent ou non dans les faits saillants."],
    ["Compétition résiliente", "Dans le hockey sur glace professionnel nord-américain, il faut remporter 16 matchs sur un maximum possible de 28 pour gagner le championnat. Les joueurs ne réussiront pas tous, mais chacun de ceux qui obtiennent la chance de participer à ce tournoi lutte jusqu’au bout avec une résilience remarquable, malgré la douleur et les épreuves rencontrées. Bien que les patients ne demandent pas à participer à un combat contre une maladie potentiellement mortelle, comme le cancer pédiatrique ou une maladie cardiaque, ils devraient toujours être encouragés à lutter jusqu’au bout avec une résilience remarquable, malgré les grandes difficultés et la douleur, quelle que soit l’issue. Remarque : après chaque étape du tournoi, la traditionnelle poignée de main permet à tous de célébrer les efforts déployés pour arriver jusque-là. Qu’ils réussissent ou non à soulever le trophée, les patients devraient donc toujours être honorés et reconnus pour avoir fait preuve de résilience jusqu’au bout."],
    ["Mascottes amicales du quartier", "Dans le sport, une mascotte accueillante et attachante peut rendre l’expérience mémorable et créer de nombreux souvenirs heureux pour les partisans comme pour les joueurs. Il en va de même au hockey sur glace. Dans notre milieu de recherche adapté aux enfants, ces mascottes joueraient un rôle important pour soutenir le moral des patients et du personnel."],
    ["Rire", "Rien ne vaut les folies d’une mascotte de hockey bien-aimée pour faire rire de joie les partisans et les joueurs. Le combat contre une maladie potentiellement mortelle, comme le cancer pédiatrique ou une maladie cardiaque, s’accompagne de nombreuses émotions négatives, mais un rire bienfaisant peut remplir une aire de traitement de joie et offrir une pause bienvenue dans les routines cliniques."],
    ["Enthousiasme", "La dépression est malheureusement bien connue des patients qui luttent contre une maladie potentiellement mortelle, comme le cancer pédiatrique ou une maladie cardiaque. Toutefois, la visite au bon moment d’une mascotte de hockey enthousiaste et bien-aimée peut égayer même les journées les plus sombres en créant des souvenirs remplis de plaisir."],
    ["Travail d’équipe", "Une mascotte de hockey bien-aimée incarne l’esprit d’équipe. Qu’elle danse pour énergiser la foule, lance des chandails à l’aide d’un canon ou rende l’équipe visiteuse folle, elle se concentre sur le soutien à l’équipe locale, quoi qu’il arrive. Cette énergie collective peut rendre un milieu de recherche adapté aux enfants et inspiré du hockey très encourageant pour les patients qui y entrent, qu’elle provienne d’un gros ourson offrant des câlins ou d’un membre du personnel préféré qui fait sourire un patient chaque fois qu’il entre dans la pièce."],
    ["Arénas impressionnants", "Il est vrai que le hockey sur glace peut se jouer sur un étang gelé dans une cour ou dans une patinoire communautaire, mais rien ne se compare vraiment à l’expérience de visiter le splendide aréna d’une équipe professionnelle, peu importe l’issue du match. Un milieu de recherche clinique n’est généralement pas un endroit que les gens souhaitent visiter. Lorsqu’ils doivent s’y rendre, il devrait néanmoins inspirer le respect et soutenir le moral, quelle que soit l’issue, comme le fait un aréna professionnel de hockey sur glace bien conçu."],
    ["Soutien exprimé", "Les meilleurs arénas ont le meilleur personnel, qui répond à tous les besoins avec le sourire. Prendre soin de patients atteints d’une maladie potentiellement mortelle, comme le cancer pédiatrique ou une maladie cardiaque, peut apporter à la fois de la joie et du chagrin, parfois au cours de la même journée ou de la même heure. Un environnement novateur axé sur le moral des patients peut également rendre le milieu de travail plus agréable pour le personnel et ainsi améliorer la qualité des soins reçus par tous ceux qui l’entourent. N’oublions pas que les membres du personnel sont eux aussi des patients."],
    ["Avantage de la glace locale", "Pour certains patients, le parcours exige de passer de longues périodes loin du confort de leur foyer. Le milieu de recherche adapté aux enfants et inspiré du hockey sur glace comprendrait des logements sur place destinés aux patients et aux membres du personnel admissibles afin de soutenir leur moral en leur procurant un « avantage de la glace locale » pendant leur combat contre une maladie potentiellement mortelle, comme le cancer pédiatrique ou une maladie cardiaque."],
    ["La pratique fait une différence", "La partie la plus importante d’un match de hockey se déroule avant que l’arbitre laisse tomber la rondelle : ce sont les habiletés pratiquées pendant l’échauffement et en coulisses qui font toute la différence. Les patients qui luttent contre une maladie potentiellement mortelle ne sont pas tous considérés comme des cas de recherche, mais chaque cas peut fournir de précieux enseignements. Une maladie potentiellement mortelle n’est jamais un « cas typique » pour les patients, et chaque leçon apprise peut sauver une vie."],
    ["Quelqu’un a parlé de nourriture?", "L’un des aspects les plus mémorables des arénas impressionnants est la grande variété d’aliments qui y sont offerts, particulièrement dans les établissements qui mettent en valeur la cuisine régionale, comme le barbecue et la poutine. Les hôpitaux ne sont généralement pas reconnus pour leur cuisine, mais notre milieu de recherche adapté aux enfants et inspiré du hockey sur glace accorderait la priorité à des repas délicieux pour les patients et le personnel, sans sacrifier la nutrition ni négliger les plans de soins. Remarque : selon Here to Serve, Inc., à Los Angeles, en Californie, 60 % du combat contre le cancer se déroule à la maison. Il est donc important de faire notre part pour que les patients reçoivent des repas nutritifs non seulement dans un établissement clinique, mais aussi lorsqu’ils rentrent chez eux après de longues heures de traitement."],
    ["L’équipement compte", "Le hockey sur glace ne peut se jouer sans équipement spécialisé. Il en va de même pour les patients qui luttent contre une maladie potentiellement mortelle, comme le cancer pédiatrique ou une maladie cardiaque."],
    ["Rondelles de caoutchouc et bâtons de hockey", "Le principe fondamental du hockey sur glace consiste à faire progresser, à l’aide d’un bâton, une rondelle de caoutchouc de trois pouces sur une patinoire de 200 pieds remplie d’obstacles. Une bonne circulation de la rondelle est donc essentielle au succès. Chaque patient qui reçoit un diagnostic de maladie potentiellement mortelle, comme le cancer pédiatrique ou une maladie cardiaque, se voit communiquer un taux de survie. Il doit ensuite composer avec ce pourcentage et traverser un environnement rempli d’obstacles afin de le dépasser ou de l’améliorer, selon le point de vue. Comme le bâton de hockey, la santé physique, émotionnelle et mentale est tout ce dont le patient dispose pour faire progresser la rondelle sur la glace. Il importe donc de lui donner toutes les chances de réussir à patiner jusqu’au but. Un milieu de recherche adapté aux enfants et inspiré du hockey sur glace peut offrir des soins cliniques qui protègent la santé physique et soutenir le moral afin de protéger la santé émotionnelle et mentale."],
    ["Glace propre (surfaceuses Zamboni)", "Entre les périodes d’un match de hockey sur glace, la surfaceuse Zamboni est l’une des pièces d’équipement les plus importantes. Elle nettoie la glace afin que le jeu soit de la plus grande qualité possible au début de chaque période de 20 minutes. De la même façon, dans un milieu de recherche adapté aux enfants, un entretien rigoureux de l’environnement est essentiel pour que les patients puissent recevoir des traitements de la plus grande qualité possible."],
  ],
} satisfies Record<Locale, [string, string][]>;

const hockeyEnvironmentH2Headings = new Set([
  "Artistically Competitive",
  "Friendly Neighborhood Mascots",
  "Impressive Arenas",
  "Equipment Matters",
  "Artistique et compétitif",
  "Mascottes amicales du quartier",
  "Arénas impressionnants",
  "L’équipement compte",
]);

const createHockeyEnvironmentSections = (locale: Locale) =>
  hockeyEnvironmentSections[locale].map(([heading, paragraph]) => ({
    heading,
    ...(hockeyEnvironmentH2Headings.has(heading) ? {} : { headingLevel: 3 as const }),
    paragraphs: [paragraph],
  }));

